// Enemy image assets as base64 data URIs

// THUG - small (48px) for map markers
export const THUG_MAP_IMAGE = 'data:image/png;base64,';

// THUG - medium (128px) for battle screen & popups
export const THUG_BATTLE_IMAGE = 'data:image/png;base64,';

// SUPER_THUG - small (48px) for map markers
export const SUPER_THUG_MAP_IMAGE = 'data:image/png;base64,';

// SUPER_THUG - medium (128px) for battle screen & popups
export const SUPER_THUG_BATTLE_IMAGE = 'data:image/png;base64,';

// BANDIT - small (48px) for map markers
export const BANDIT_MAP_IMAGE = 'data:image/png;base64,';

// BANDIT - medium (128px) for battle screen & popups
export const BANDIT_BATTLE_IMAGE = 'data:image/png;base64,';

// VILLAIN - small (48px) for map markers
export const VILLAIN_MAP_IMAGE = 'data:image/png;base64,';

// VILLAIN - medium (128px) for battle screen & popups
export const VILLAIN_BATTLE_IMAGE = 'data:image/png;base64,';

// CRIMINAL - small (48px) for map markers
export const CRIMINAL_MAP_IMAGE = 'data:image/png;base64,';

// CRIMINAL - medium (128px) for battle screen & popups
export const CRIMINAL_BATTLE_IMAGE = 'data:image/png;base64,';

// GANGSTER - small (48px) for map markers
export const GANGSTER_MAP_IMAGE = 'data:image/png;base64,';

// GANGSTER - medium (128px) for battle screen & popups
export const GANGSTER_BATTLE_IMAGE = 'data:image/png;base64,';

// Lookup maps by enemy name (lowercase)
export const ENEMY_MAP_IMAGES: Record<string, string> = {
  'thug': THUG_MAP_IMAGE,
  'super thug': SUPER_THUG_MAP_IMAGE,
  'bandit': BANDIT_MAP_IMAGE,
  'villain': VILLAIN_MAP_IMAGE,
  'criminal': CRIMINAL_MAP_IMAGE,
  'gangster': GANGSTER_MAP_IMAGE,
};

export const ENEMY_BATTLE_IMAGES: Record<string, string> = {
  'thug': THUG_BATTLE_IMAGE,
  'super thug': SUPER_THUG_BATTLE_IMAGE,
  'bandit': BANDIT_BATTLE_IMAGE,
  'villain': VILLAIN_BATTLE_IMAGE,
  'criminal': CRIMINAL_BATTLE_IMAGE,
  'gangster': GANGSTER_BATTLE_IMAGE,
};

export const getEnemyMapImage = (name: string): string | null => {
  const lower = name.toLowerCase();
  for (const [key, val] of Object.entries(ENEMY_MAP_IMAGES)) {
    if (lower.includes(key)) return val;
  }
  return null;
};

export const getEnemyBattleImage = (name: string): string | null => {
  const lower = name.toLowerCase();
  for (const [key, val] of Object.entries(ENEMY_BATTLE_IMAGES)) {
    if (lower.includes(key)) return val;
  }
  return null;
};
